import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BI-oZTPy.js";const c=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function o(r,e,d,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Download a build from the <a href="https://github.com/wieluk/gameyfin-app/releases" target="_blank" rel="noreferrer">releases</a> page.</p><table tabindex="0"><thead><tr><th>System</th><th>File</th><th>Notes</th></tr></thead><tbody><tr><td>Windows</td><td><code>.exe</code></td><td>Not code signed, so SmartScreen warns on first run. Choose <strong>More info</strong>, then <strong>Run anyway</strong>.</td></tr><tr><td>Debian, Ubuntu</td><td><code>.deb</code></td><td>Needs Ubuntu 24.04 or Debian 13 or newer. Gameyfin tells you when a new version is out; install it the same way.</td></tr><tr><td>Fedora, openSUSE</td><td><code>.rpm</code></td><td>Needs Fedora 40, openSUSE Leap 16 or Tumbleweed, or newer. Updates work as with <code>.deb</code>.</td></tr><tr><td>Any Linux</td><td><code>.flatpak</code></td><td>Works on older distributions too, since it brings its own libraries.</td></tr></tbody></table><p>The <code>.deb</code> and <code>.rpm</code> need glibc 2.39 or newer and WebKitGTK 4.1. On anything older, use the Flatpak.</p><h3 id="flatpak-updates" tabindex="-1">Flatpak: updates <a class="header-anchor" href="#flatpak-updates" aria-label="Permalink to &quot;Flatpak: updates&quot;">​</a></h3><p>You can also install from the repository instead of a file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --if-not-exists</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gameyfin-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://wieluk.github.io/gameyfin-app/repo/gameyfin-app.flatpakrepo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gameyfin-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.gameyfin.gameyfin-app</span></span></code></pre></div><h3 id="flatpak-32-bit-support" tabindex="-1">Flatpak: 32-bit support <a class="header-anchor" href="#flatpak-32-bit-support" aria-label="Permalink to &quot;Flatpak: 32-bit support&quot;">​</a></h3><p>Installers and older games are 32-bit, and the Flatpak needs Flathub&#39;s 32-bit libraries to run them with Proton. Without them those run on Gameyfin&#39;s own Wine instead. <strong>Settings, Compatibility</strong> offers <strong>Install 32-bit support</strong>; restart Gameyfin afterwards.</p><h2 id="first-start" tabindex="-1">First start <a class="header-anchor" href="#first-start" aria-label="Permalink to &quot;First start&quot;">​</a></h2><ol><li><strong>Connect</strong>: enter your <a href="https://github.com/gameyfin/gameyfin" target="_blank" rel="noreferrer">Gameyfin</a> server&#39;s address.</li><li><strong>Sign in</strong>: the server&#39;s own login page opens, so SSO works too. If the login window misbehaves, use the link under it to clear its saved data.</li><li><strong>Choose where games go and name this PC.</strong> The name appears beside every save this PC uploads.</li></ol><p>On Linux, what Windows games need downloads on a game&#39;s first launch. See <a href="./playing">Playing games</a>.</p><h2 id="behind-a-proxy-with-its-own-login" tabindex="-1">Behind a proxy with its own login <a class="header-anchor" href="#behind-a-proxy-with-its-own-login" aria-label="Permalink to &quot;Behind a proxy with its own login&quot;">​</a></h2><p>A proxy that asks to sign in before Gameyfin, such as Pangolin or Authelia, is signed in through the same window, and its cookie is kept alongside your Gameyfin login. Its session expires on its own schedule, and Gameyfin then asks you to sign in again.</p><p>To be asked less often, raise the proxy&#39;s session lifetime, or let <code>/connect/**</code>, <code>/download/**</code>, <code>/images/**</code> and <code>/saves/**</code> through without it. Gameyfin&#39;s own login still guards them. A proxy that authenticates by <code>Authorization</code> header, such as HTTP Basic, cannot be used: staying signed in needs that header.</p><h2 id="your-games-folder" tabindex="-1">Your games folder <a class="header-anchor" href="#your-games-folder" aria-label="Permalink to &quot;Your games folder&quot;">​</a></h2><p>Everything lives in a <code>Gameyfin</code> folder inside the games folder you chose:</p><table tabindex="0"><thead><tr><th>Folder</th><th>Holds</th></tr></thead><tbody><tr><td><code>Downloads</code></td><td>Downloaded archives and unpacked files waiting to install</td></tr><tr><td><code>Installations</code></td><td>Installed games, named <code>(id) Title</code></td></tr><tr><td><code>Prefixes</code></td><td>One Windows environment per Windows game (Linux only)</td></tr><tr><td><code>Saves</code></td><td>Local copies of save backups before they are uploaded</td></tr></tbody></table><p>Because the game id is in the folder name, Gameyfin can find your games again after a reinstall. Use <strong>Rescan folders</strong> in Installed or Downloads.</p><p>You can add more games folders, for example on a second drive, in <strong>Settings, Library</strong>.</p>`,21)])])}const u=t(n,[["render",o]]);export{c as __pageData,u as default};
